/**
 * route-scorer.mjs — deterministic skill/agent routing for intent-classifier.js.
 *
 * Scores a prompt against ccc-routes.json (generated by scripts/build-routes.js)
 * and renders the short <ccc-route> / <ccc-next> blocks injected into the
 * model's context. Pure functions only: no filesystem writes, no prompt
 * logging. Shared verbatim by the Claude Code and Codex plugins.
 *
 * Scoring (capped at 1.0):
 *   intent pattern (regex)        +0.60 each distinct, at most two
 *   strong trigger (distinctive)  +0.60
 *   curated trigger, multi-word   +0.35
 *   curated trigger, single word  +0.25
 *   description phrase            +0.25
 *   path/file mention             +0.20
 *   negative pattern              route removed
 * Ties sort by route priority (route-hints.json, default 0), then skill first.
 * Tiers: high  = intent pattern hit, top >= 0.8, 0.25 lead over runner-up
 *        medium = top >= 0.55 (one generic keyword alone never fires)
 *        low   = silent
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const HIGH_THRESHOLD = 0.8;
export const HIGH_MARGIN = 0.25;
export const MEDIUM_THRESHOLD = 0.55;
export const MAX_CONTEXT_CHARS = 600;
const MIN_LISTED_SCORE = 0.3;
// Two next steps + "Done for now" + this = AskUserQuestion's 4-option cap.
export const MUTE_NEXT_LABEL = 'Stop suggesting next steps';
const ANALYZED_CHARS = 600;

const WEIGHTS = { pattern: 0.6, strong: 0.6, phrase: 0.35, word: 0.25, desc: 0.25, path: 0.2 };

let cachedRoutes = null;

export function loadRoutes(file = join(dirname(fileURLToPath(import.meta.url)), 'ccc-routes.json')) {
  if (cachedRoutes && cachedRoutes.file === file) return cachedRoutes.routes;
  const routes = JSON.parse(readFileSync(file, 'utf8')).routes.map(compileRoute);
  cachedRoutes = { file, routes };
  return routes;
}

function escapeRegex(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Whole-word phrase: "post" must not match "postgres", "review" must not
// match "preview". The last word may take a plural s/es.
function phraseRegex(phrase) {
  const body = phrase.split(/\s+/).map(escapeRegex).join('[\\s-]+');
  const plural = /[a-z]$/i.test(phrase) ? '(?:s|es)?' : '';
  return new RegExp(`(?<![\\w-])${body}${plural}(?![\\w-])`, 'i');
}

function pathRegex(p) {
  // ".go" → a file name ending in .go; "Dockerfile" → that word.
  if (p.startsWith('.') && !p.includes('/')) return new RegExp(`\\w${escapeRegex(p)}(?![\\w.])`, 'i');
  return new RegExp(`(?<![\\w-])${escapeRegex(p)}(?![\\w-])`, 'i');
}

function compileRoute(route) {
  return {
    ...route,
    _triggers: [
      ...route.strong.map((t) => ({ re: phraseRegex(t), weight: WEIGHTS.strong })),
      ...route.triggers.map((t) => ({ re: phraseRegex(t), weight: /\s/.test(t) ? WEIGHTS.phrase : WEIGHTS.word })),
    ],
    _desc: route.descTriggers.map((t) => phraseRegex(t)),
    _patterns: route.patterns.map((p) => new RegExp(p, 'i')),
    _negatives: route.negatives.map((p) => new RegExp(p, 'i')),
    _paths: route.paths.map(pathRegex),
  };
}

/**
 * Why this prompt must not be routed, or null. Explicit commands and
 * machine-generated turns (task notifications, loop ticks, sub-agent
 * reports, hook-injected tags) are never routed.
 */
export function skipReason(rawPrompt, payload = {}) {
  const prompt = String(rawPrompt || '').trim();
  if (!prompt) return 'empty';
  if (/^[/$][\w:-]+/.test(prompt)) return 'explicit-command';
  if (/^<[\w-]+[\s>]/.test(prompt)) return 'non-human';
  if (/^\[SYSTEM NOTIFICATION/i.test(prompt)) return 'non-human';
  if (/<<autonomous-loop/.test(prompt)) return 'non-human';
  if (payload.agent_id || payload.agent_type) return 'subagent';
  return null;
}

/** Lowercased routing text: code, URLs and quoted pastes removed, first 600 chars. */
export function normalizePrompt(prompt) {
  return String(prompt || '')
    .replace(/```[\s\S]*?(```|$)/g, ' ')
    .replace(/`[^`\n]*`/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/<pasted_content[\s\S]*?(<\/pasted_content[^>]*>|$)/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, ANALYZED_CHARS)
    .toLowerCase();
}

/** Score every route; returns candidates sorted by score (desc), score > 0 only. */
export function scoreRoutes(prompt, routes = loadRoutes()) {
  const text = normalizePrompt(prompt);
  if (!text) return [];
  const candidates = [];
  for (const route of routes) {
    if (route._negatives.some((re) => re.test(text))) continue;
    if (route.requirePath && !route._paths.some((re) => re.test(text))) continue;
    let score = 0;
    let patternHits = 0;
    for (const re of route._patterns) {
      if (patternHits < 2 && re.test(text)) {
        score += WEIGHTS.pattern;
        patternHits += 1;
      }
    }
    for (const t of route._triggers) if (t.re.test(text)) score += t.weight;
    for (const re of route._desc) if (re.test(text)) score += WEIGHTS.desc;
    for (const re of route._paths) if (re.test(text)) score += WEIGHTS.path;
    if (score > 0) candidates.push({ route, score: Math.min(1, Math.round(score * 100) / 100), patternHits });
  }
  // Ties: higher route-hints priority first, then skills before agents (a
  // skill is the cheaper, in-thread path).
  const kindRank = (c) => (c.route.kind === 'skill' ? 0 : 1);
  candidates.sort((a, b) => b.score - a.score || (b.route.priority || 0) - (a.route.priority || 0) || kindRank(a) - kindRank(b));
  return candidates;
}

const ROUTE_MODES = ['off', 'suggest', 'auto'];

function validMode(value) {
  const mode = String(value || '').trim().toLowerCase();
  return ROUTE_MODES.includes(mode) ? mode : null;
}

/**
 * Route mode: off | suggest | auto. A valid CCC_ROUTE_MODE wins, then the
 * lane's saved `routeMode` preference (config.json, set by /ccc-settings),
 * then auto. Unknown values are ignored.
 */
export function routeMode(env = process.env, saved = null) {
  return validMode(env.CCC_ROUTE_MODE) || validMode(saved) || 'auto';
}

export function tierFor(candidates, mode = 'auto') {
  if (mode === 'off' || !candidates.length) return 'low';
  const [top, second] = candidates;
  if (top.score < MEDIUM_THRESHOLD) return 'low';
  const clearWinner = top.score >= HIGH_THRESHOLD && top.score - (second ? second.score : 0) >= HIGH_MARGIN;
  // Topic scores alone cannot authorize an auto-run. Curated patterns must
  // express a request to do this skill's job, not merely name its subject.
  // Manual (disable-model-invocation) skills and agents never auto-run.
  if (clearWinner && top.patternHits > 0 && mode === 'auto' && top.route.kind === 'skill' && !top.route.manual) return 'high';
  return 'medium';
}

/** claude-code | codex. */
export function detectHost(env = process.env, moduleUrl = import.meta.url) {
  if (env.CCC_SOURCE_APP === 'codex' || env.CCC_SOURCE_APP === 'claude-code') return env.CCC_SOURCE_APP;
  if (env.PLUGIN_ROOT || /cowork-plugin-codex|\/\.codex\//.test(moduleUrl)) return 'codex';
  return 'claude-code';
}

function invokeText(route, host) {
  if (route.kind === 'agent') return `${route.invoke} agent`;
  return host === 'codex' ? `$${route.id}` : route.invoke;
}

function optionText(route, host) {
  const manual = route.manual ? ' (user types it)' : '';
  const fresh = route.kind === 'agent' ? ' (fresh context)' : '';
  return `${invokeText(route, host)}: ${route.label}${manual}${fresh}`;
}

// Option counts include the trailing "Just answer": AskUserQuestion takes up
// to 4 options, Codex request_user_input 2-3 (its client adds "Other").
// CCC_ROUTE_MENU=list swaps the native picker for a numbered list; the host
// (and so skill naming) is unchanged.
function useList(env = process.env) {
  return String(env.CCC_ROUTE_MENU || '').toLowerCase() === 'list';
}

function menuInstruction(host, count) {
  if (useList()) return 'Show a numbered list, best first, plus "Just answer".';
  if (host === 'codex') {
    return `Call request_user_input once: 1 question, ${count + 1} options, best first with "(Recommended)", last "Just answer".`;
  }
  return `Call AskUserQuestion once: 1 question, ${count + 1} options, best first marked 🟢, last "Just answer".`;
}

function clamp(text) {
  return text.length <= MAX_CONTEXT_CHARS ? text : `${text.slice(0, MAX_CONTEXT_CHARS - 14)}…</ccc-route>`;
}

/** The <ccc-route> block for the model, or null for the low tier. */
export function renderRouteContext(candidates, tier, host) {
  if (tier === 'low' || !candidates.length) return null;
  // Weak tail candidates only add menu noise.
  const top3 = candidates.slice(0, 3).filter((c, i) => i === 0 || c.score >= MIN_LISTED_SCORE);
  const list = top3.map((c) => `${invokeText(c.route, host)} ${c.score.toFixed(2)}`).join(' | ');
  let body;
  if (tier === 'high') {
    const top = top3[0].route;
    const how = host === 'codex' ? `use the ${top.id} skill` : `invoke Skill commander:${top.id}`;
    body = `Clear match: ${how} now (${top.label}). Say so in one line first. Skip it if the user only wants a quick answer.`;
  } else if (top3[0].route.manual) {
    // Hidden (disable-model-invocation) skill: the host blocks Skill calls to
    // it, so offer it with the alternatives instead of invoking it (CC-2112).
    // Kept short: paid on every matching prompt (one option ~65 tokens).
    const shown = top3.slice(0, host === 'codex' ? 2 : 3);
    const opts = shown.map((c) => `${invokeText(c.route, host)}: ${c.route.label}${c.route.manual ? '*' : ''}`).join('; ');
    const ask = host === 'claude-code' && !useList() ? 'Offer via AskUserQuestion once, 🟢 first, last "Just answer":' : `${menuInstruction(host, shown.length)} Options:`;
    body = `Hidden skill. ${ask} ${opts}. *User types it; never invoke it.`;
  } else {
    const shown = top3.slice(0, host === 'codex' ? 2 : 3);
    const opts = shown.map((c) => optionText(c.route, host)).join('; ');
    body = `Possible fit. ${menuInstruction(host, shown.length)} Options: ${opts}. Run the pick; manual skills need the user to type them; agents spawn with fresh context.`;
  }
  return clamp(`<ccc-route tier="${tier}" candidates="${list}">\n${body}\n</ccc-route>`);
}

/** The <ccc-next> block offered after a skill finished, or null. */
export function renderNextContext(fromRoute, nextRoutes, host) {
  if (!fromRoute || !nextRoutes.length) return null;
  const opts = nextRoutes.slice(0, 2).map((r) => optionText(r, host)).join('; ');
  const extra = host === 'codex' ? ' plus "Done for now"' : ' plus "Done for now" and "' + MUTE_NEXT_LABEL + '"';
  const ask = useList()
    ? 'Show a short numbered list.'
    : host === 'codex'
      ? 'Call request_user_input once (1 question, max 3 options, first with "(Recommended)").'
      : 'Call AskUserQuestion once (1 question, max 4 options, first marked 🟢).';
  const text = `<ccc-next after="${invokeText(fromRoute, host)}">\n${invokeText(fromRoute, host)} finished. Offer what's next. ${ask} Options: ${opts}${extra}. Run the pick; otherwise stop.\n</ccc-next>`;
  return text.length <= MAX_CONTEXT_CHARS ? text : `${text.slice(0, MAX_CONTEXT_CHARS - 13)}…</ccc-next>`;
}

